#!/usr/bin/env python3
"""Remove duplicate events sharing an event_id from events.jsonl."""

import json

SEEN = set()
OUTPUT = []

with open("events.jsonl", "r", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        event = json.loads(line)
        event_id = event["event_id"]
        if event_id in SEEN:
            continue
        SEEN.add(event_id)
        OUTPUT.append(event)

with open("deduped.jsonl", "w", encoding="utf-8") as f:
    for event in OUTPUT:
        f.write(json.dumps(event) + "\n")
