#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events sharing an event_id, write deduped.jsonl."""

import json

def main():
    seen = set()
    out = []
    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid not in seen:
                seen.add(eid)
                out.append(event)

    with open("deduped.jsonl", "w") as f:
        for event in out:
            f.write(json.dumps(event, separators=(",", ":")) + "\n")

if __name__ == "__main__":
    main()

