#!/usr/bin/env python3
"""Print report filenames in report order (numerical)."""

import os
import re


def report_key(name: str) -> int:
    m = re.search(r"report-(\d+)", name)
    return int(m.group(1)) if m else 0


def main() -> None:
    names = [f for f in os.listdir("reports") if os.path.isfile(os.path.join("reports", f))]
    for name in sorted(names, key=report_key):
        print(name)


if __name__ == "__main__":
    main()

