#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re
import sys

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> tuple:
    """Extract (number,) for sorting report-N.txt files numerically."""
    m = re.match(r"report-(\d+)\.txt", filename)
    if m:
        return (int(m.group(1)),)
    # Non-matching names sort after numbered ones
    return (sys.maxsize, filename)


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: directory '{REPORTS_DIR}' not found", file=sys.stderr)
        sys.exit(1)

    # Filter to regular files only
    files = [f for f in entries if os.path.isfile(os.path.join(REPORTS_DIR, f))]
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

