"""Rotate old entries from app.log to archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days before AS_OF
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    with open("app.log") as f:
        lines = f.readlines()

    kept: list[str] = []
    archived: list[str] = []

    for line in lines:
        # Preserve empty lines / lines without a valid timestamp as kept
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff_dt:
            archived.append(line)
        else:
            kept.append(line)

    if archived:
        with open("archive.log", "a") as f:
            f.writelines(archived)

    with open("app.log", "w") as f:
        f.writelines(kept)


if __name__ == "__main__":
    main()

