"""rotate.py — rotate app.log entries older than 7 days before AS_OF into archive.log.

Usage: python rotate.py AS_OF
"""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse the leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    # Read all lines from app.log
    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found.", file=sys.stderr)
        sys.exit(1)

    # Strip newline (but keep lines for later re-joining)
    lines = [line.rstrip("\n") for line in lines]

    # Separate stale and fresh entries, preserving order
    stale: list[str] = []
    fresh: list[str] = []

    for line in lines:
        if not line:
            continue
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            stale.append(line)
        else:
            fresh.append(line)

    # Append stale entries to archive.log
    if stale:
        with open("archive.log", "a") as f:
            for entry in stale:
                f.write(entry + "\n")

    # Rewrite app.log with fresh entries
    with open("app.log", "w") as f:
        for entry in fresh:
            f.write(entry + "\n")

    print(f"Rotated: {len(stale)} entries moved to archive.log, {len(fresh)} remaining in app.log")


if __name__ == "__main__":
    main()

